import { describe, expect, it } from 'vitest'

import fixtures from './__fixtures__/cst.json'
import {
  CST_ORDER,
  cosineSpacing,
  cstSurface,
  leadingEdgeRadius,
  sectionLoop,
  sectionMetrics,
  shapeFunction,
} from './cst'

/**
 * The fixture is generated by `tools/solver/make_ts_fixtures.py` from the Python implementation
 * the dataset was produced with. If these fail, the two evaluators have drifted and the browser is
 * drawing a different aerofoil from the one the surrogate was trained on.
 */
describe('parity with the Python evaluator', () => {
  it('uses the same weight count', () => {
    expect(fixtures.cstOrder).toBe(CST_ORDER)
  })

  for (const testCase of fixtures.cases) {
    describe(testCase.name, () => {
      it('matches the upper surface to 1e-9', () => {
        testCase.psi.forEach((psi, index) => {
          expect(cstSurface(testCase.upperWeights, psi)).toBeCloseTo(testCase.upperZ[index]!, 9)
        })
      })

      it('matches the lower surface to 1e-9', () => {
        testCase.psi.forEach((psi, index) => {
          expect(cstSurface(testCase.lowerWeights, psi)).toBeCloseTo(testCase.lowerZ[index]!, 9)
        })
      })

      it('matches the derived metrics to 1e-9', () => {
        const metrics = sectionMetrics(testCase.upperWeights, testCase.lowerWeights)
        expect(metrics.thicknessMax).toBeCloseTo(testCase.metrics.thicknessMax, 9)
        expect(metrics.thicknessMaxX).toBeCloseTo(testCase.metrics.thicknessMaxX, 9)
        expect(metrics.camberMax).toBeCloseTo(testCase.metrics.camberMax, 9)
        expect(metrics.camberMaxX).toBeCloseTo(testCase.metrics.camberMaxX, 9)
        expect(metrics.leRadius).toBeCloseTo(testCase.metrics.leRadius, 12)
        expect(metrics.area).toBeCloseTo(testCase.metrics.area, 9)
      })

      it('builds the same loop', () => {
        const loop = sectionLoop(testCase.upperWeights, testCase.lowerWeights, 160)
        expect(loop).toHaveLength(testCase.loopLength)
        testCase.loopHead.forEach(([x, z], index) => {
          expect(loop[index]!.x).toBeCloseTo(x!, 12)
          expect(loop[index]!.z).toBeCloseTo(z!, 12)
        })
      })
    })
  }
})

describe('cstSurface', () => {
  const weights = Array.from({ length: CST_ORDER }, () => 0.2)

  it('closes at both edges', () => {
    expect(cstSurface(weights, 0)).toBe(0)
    expect(cstSurface(weights, 1)).toBe(0)
    expect(cstSurface(weights, 0.5)).toBeGreaterThan(0)
  })

  it('rejects the wrong weight count', () => {
    expect(() => shapeFunction([0.1, 0.2], 0.5)).toThrow(RangeError)
  })

  it('scales linearly with the weights', () => {
    const doubled = weights.map((w) => w * 2)
    expect(cstSurface(doubled, 0.3)).toBeCloseTo(2 * cstSurface(weights, 0.3), 12)
  })
})

describe('leadingEdgeRadius', () => {
  it('follows the closed form', () => {
    expect(leadingEdgeRadius(0.2)).toBeCloseTo(0.02, 12)
  })
})

describe('cosineSpacing', () => {
  it('spans the chord and clusters at both edges', () => {
    const x = cosineSpacing(65)
    expect(x[0]).toBe(0)
    expect(x[64]).toBeCloseTo(1, 12)
    const gaps = Array.from({ length: 64 }, (_, j) => x[j + 1]! - x[j]!)
    expect(gaps[0]!).toBeLessThan(gaps[32]! / 4)
    expect(gaps[0]!).toBeCloseTo(gaps[63]!, 12)
  })

  it('rejects degenerate counts', () => {
    expect(() => cosineSpacing(1)).toThrow(RangeError)
  })
})

describe('sectionLoop', () => {
  const upper = Array.from({ length: CST_ORDER }, () => 0.2)
  const lower = Array.from({ length: CST_ORDER }, () => -0.15)

  it('starts and ends at the trailing edge', () => {
    const loop = sectionLoop(upper, lower, 160)
    expect(loop).toHaveLength(161)
    expect(loop[0]).toEqual({ x: 1, z: 0 })
    expect(loop[160]).toEqual({ x: 1, z: 0 })
  })

  it('runs upper surface first, which is the Python ordering', () => {
    const loop = sectionLoop(upper, lower, 160)
    expect(loop[40]!.z).toBeGreaterThan(0)
    expect(loop[120]!.z).toBeLessThan(0)
  })

  it('is wound counter-clockwise, as the solver requires', () => {
    const loop = sectionLoop(upper, lower, 160)
    let twiceArea = 0
    for (let i = 0; i < loop.length - 1; i += 1) {
      twiceArea += loop[i]!.x * loop[i + 1]!.z - loop[i + 1]!.x * loop[i]!.z
    }
    expect(twiceArea).toBeGreaterThan(0)
  })

  it('rejects an odd panel count', () => {
    expect(() => sectionLoop(upper, lower, 61)).toThrow(RangeError)
  })
})
